package com.ligamunicipal.api.model; import jakarta.persistence.*; import jakarta.validation.constraints.*; import java.time.*;
@Entity @Table(uniqueConstraints=@UniqueConstraint(columnNames={"partido_id","miembroVotante_id","jugadorEvaluado_id"}), indexes=@Index(columnList="partido_id")) public class VotoJornada extends BaseEntity { @ManyToOne(optional=false) public PartidoJornada partido; @ManyToOne(optional=false) public MiembroEquipo miembroVotante; @ManyToOne(optional=false) public JugadorPlantilla jugadorEvaluado; @Min(-2) @Max(10) public int nota; public boolean votoMvp; public Instant fechaVoto=Instant.now(); }
